-- Jeu de LecteurNonInscrits / EcrivainNonInscrits (« Non-inscrits », PROC_CNI), lot 14 du plan-676a4b19. Identifiants 24009 6x.
-- Ce jeu est joue AVANT ceux qui creent NON_INSCRIT (PROC_DAS, PROC_NF), ETABLISSEMENT (PROC_DBE_INJ) et CIVILITE (PROC_MANDATAIRE) : il
-- leur donne la definition de ces jeux (cle seule, ou leurs colonnes), plus les colonnes que la creation ecrit, NULLABLES (les INSERT des
-- autres jeux nomment leurs colonnes). Types de RIG_DEV : NON_INSCRIT.sql, ETABLISSEMENT.cs, CIVILITE.sql, TYPE_NON_INSCRIT.sql.
IF OBJECT_ID(N'v2.NON_INSCRIT') IS NULL
    CREATE TABLE v2.NON_INSCRIT (NINSC_ID_NINSC int NOT NULL PRIMARY KEY);
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_ID_RPRTR') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_ID_RPRTR int NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_NUM_SIREN') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_NUM_SIREN varchar(9) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_CIVILITE') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_CIVILITE varchar(7) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_PATRONYME') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_PATRONYME varchar(70) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_PRENOMS') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_PRENOMS varchar(70) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_NOM_USAGE') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_NOM_USAGE varchar(70) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_DATE_NAISSANCE') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_DATE_NAISSANCE datetime NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_DEPARTEMENT_NAISS') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_DEPARTEMENT_NAISS varchar(3) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_PAYS') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_PAYS varchar(3) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_NATIONALITE') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_NATIONALITE varchar(3) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_DENOMINATION') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_DENOMINATION varchar(max) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_FORME_JURIDIQUE_UTI') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_FORME_JURIDIQUE_UTI varchar(10) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_TYPE_NON_INSCRIT') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_TYPE_NON_INSCRIT varchar(5) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_ETAT_INFO') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_ETAT_INFO varchar(1) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_NUM_NON_INSCRIT') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_NUM_NON_INSCRIT varchar(11) NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_PRINCIPAL') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_PRINCIPAL bit NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_INSCRIT_REGISTRE_METIER') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_INSCRIT_REGISTRE_METIER bit NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_DATE_MAJ') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_DATE_MAJ datetime NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_PM') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_PM bit NULL;
IF COL_LENGTH('v2.NON_INSCRIT', 'NINSC_NI_SECONDAIRE') IS NULL ALTER TABLE v2.NON_INSCRIT ADD NINSC_NI_SECONDAIRE bit NULL;
IF OBJECT_ID(N'v2.ETABLISSEMENT') IS NULL
    CREATE TABLE v2.ETABLISSEMENT (ETBLS_ID_ETBLS int NOT NULL PRIMARY KEY, ETBLS_ID_ADRBS int NULL, ETBLS_ID_DSRCS int NULL,
        ETBLS_TYPE_ADRESSE varchar(10) NULL);
IF COL_LENGTH('v2.ETABLISSEMENT', 'ETBLS_SUPPRIME') IS NULL ALTER TABLE v2.ETABLISSEMENT ADD ETBLS_SUPPRIME bit NOT NULL DEFAULT (0);
IF COL_LENGTH('v2.ETABLISSEMENT', 'ETBLS_ID_NINSC') IS NULL ALTER TABLE v2.ETABLISSEMENT ADD ETBLS_ID_NINSC int NULL;
IF COL_LENGTH('v2.ETABLISSEMENT', 'ETBLS_NUM_ORDRE') IS NULL ALTER TABLE v2.ETABLISSEMENT ADD ETBLS_NUM_ORDRE int NULL;
IF COL_LENGTH('v2.ETABLISSEMENT', 'ETBLS_ACTIVITE_IDEM') IS NULL ALTER TABLE v2.ETABLISSEMENT ADD ETBLS_ACTIVITE_IDEM bit NULL;
IF COL_LENGTH('v2.ETABLISSEMENT', 'ETBLS_ETAT_INFO') IS NULL ALTER TABLE v2.ETABLISSEMENT ADD ETBLS_ETAT_INFO varchar(1) NULL;
IF COL_LENGTH('v2.ETABLISSEMENT', 'ETBLS_COMMERCIAL') IS NULL ALTER TABLE v2.ETABLISSEMENT ADD ETBLS_COMMERCIAL bit NULL;
IF COL_LENGTH('v2.ETABLISSEMENT', 'ETBLS_1ER_OUVERT_EN_FRANCE') IS NULL ALTER TABLE v2.ETABLISSEMENT ADD ETBLS_1ER_OUVERT_EN_FRANCE bit NULL;
-- CIVILITE : la definition de PROC_MANDATAIRE.sql (joue apres), plus la discriminante PP/PM, le sexe et le libelle (CIVILITE.sql).
IF OBJECT_ID(N'v2.CIVILITE') IS NULL
    CREATE TABLE v2.CIVILITE (R_CIVILITE_VALEUR varchar(7) NOT NULL PRIMARY KEY, R_CIVILITE_ABREGE_EDIT varchar(5) NOT NULL);
IF COL_LENGTH('v2.CIVILITE', 'R_CIVILITE_LIBELLE_ECRAN') IS NULL ALTER TABLE v2.CIVILITE ADD R_CIVILITE_LIBELLE_ECRAN varchar(30) NULL;
IF COL_LENGTH('v2.CIVILITE', 'R_CIVILITE_TOUJOURS_PP') IS NULL ALTER TABLE v2.CIVILITE ADD R_CIVILITE_TOUJOURS_PP bit NULL;
IF COL_LENGTH('v2.CIVILITE', 'R_CIVILITE_SEXE_MASCULIN') IS NULL ALTER TABLE v2.CIVILITE ADD R_CIVILITE_SEXE_MASCULIN bit NULL;
IF COL_LENGTH('v2.CIVILITE', 'R_CIVILITE_SEXE_FEMININ') IS NULL ALTER TABLE v2.CIVILITE ADD R_CIVILITE_SEXE_FEMININ bit NULL;
IF OBJECT_ID(N'v2.TYPE_NON_INSCRIT') IS NULL
    CREATE TABLE v2.TYPE_NON_INSCRIT (R_TYPENONINS_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_TYPENONINS_LIBELLE_ECRAN varchar(35) NOT NULL);
IF OBJECT_ID(N'v2.DEMANDE') IS NULL
    CREATE TABLE v2.DEMANDE (DMND_ID_DMND int NOT NULL PRIMARY KEY, DMND_ID_DSRCS int NULL, DMND_ID_ACTRC int NULL,
        DMND_NUM_DEMANDE varchar(11) NOT NULL, DMND_ETAT_DEMANDE varchar(1) NOT NULL, DMND_CODE_PROSS varchar(40) NULL,
        DMND_DATE_CREATION datetime NULL, DMND_DATE_VALIDATION datetime NULL);
IF COL_LENGTH('v2.DEMANDE', 'DMND_NOM') IS NULL ALTER TABLE v2.DEMANDE ADD DMND_NOM varchar(255) NULL;

EXEC sp_executesql N'
-- Les civilites de RIG_DEV (celles de PROC_MANDATAIRE.sql), leur nature et leur sexe : MR et MME toujours PP, PM jamais.
INSERT INTO v2.CIVILITE (R_CIVILITE_VALEUR, R_CIVILITE_ABREGE_EDIT)
SELECT v, a FROM (VALUES (''ME'', ''Me''), (''MR'', ''M.''), (''MME'', ''Mme''), (''ND'', ''''), (''PM'', ''PM'')) AS t(v, a)
WHERE NOT EXISTS (SELECT 1 FROM v2.CIVILITE AS c WHERE c.R_CIVILITE_VALEUR = t.v);
UPDATE v2.CIVILITE SET R_CIVILITE_TOUJOURS_PP = CASE WHEN R_CIVILITE_VALEUR IN (''MR'', ''MME'') THEN 1 ELSE 0 END,
    R_CIVILITE_SEXE_MASCULIN = CASE WHEN R_CIVILITE_VALEUR = ''MR'' THEN 1 ELSE 0 END,
    R_CIVILITE_SEXE_FEMININ = CASE WHEN R_CIVILITE_VALEUR = ''MME'' THEN 1 ELSE 0 END,
    R_CIVILITE_LIBELLE_ECRAN = CASE R_CIVILITE_VALEUR WHEN ''MR'' THEN ''Monsieur'' WHEN ''MME'' THEN ''Madame'' WHEN ''PM'' THEN ''Personne morale''
                                                      ELSE R_CIVILITE_LIBELLE_ECRAN END;
INSERT INTO v2.TYPE_NON_INSCRIT (R_TYPENONINS_VALEUR, R_TYPENONINS_LIBELLE_ECRAN) VALUES
    (''JUD'', ''Judiciaire''), (''PCOL'', ''Procédure collective''), (''AUT'', ''Autre'');
-- Les demandes CNI : validee PP (« M. BANCPP Jean »), validee PM, et une saisie interrompue (aucune ecriture de la V2).
INSERT INTO v2.DEMANDE (DMND_ID_DMND, DMND_NUM_DEMANDE, DMND_ETAT_DEMANDE, DMND_CODE_PROSS, DMND_DATE_CREATION, DMND_NOM) VALUES
    (2400961, ''26D24961'', ''V'', ''CNI'', DATEADD(day, -3, @aujourdhui), ''M. BANCPP Jean ''),
    (2400962, ''26D24962'', ''V'', ''CNI'', DATEADD(day, -2, @aujourdhui), ''BANC CNI MORALE''),
    (2400963, ''26D24963'', ''E'', ''CNI'', DATEADD(day, -1, @aujourdhui), NULL);
-- Le compteur des numeros de non-inscrit (num.Compteur, NUM-012 : RGNI), s''il manque.
IF NOT EXISTS (SELECT 1 FROM num.Compteur WHERE Type = ''RGNI'')
    INSERT INTO num.Compteur (Type, Annee, Structure, CodageAnnee, TailleChrono, Debut) VALUES (''RGNI'', 2026, ''AC'', 4, 6, 1);
IF NOT EXISTS (SELECT 1 FROM num.Compteur WHERE Type = ''DMD'')
    INSERT INTO num.Compteur (Type, Annee, Structure, CodageAnnee, Lettre, TailleChrono, Debut) VALUES (''DMD'', 2026, ''LAQC'', 2, ''D'', 5, 1);
', N'@aujourdhui datetime', @aujourdhui;
